/**
 * Finds the longest palindromic substring using expand-around-center.
 * O(n²) time, O(1) space.
 */
function parse_expression(s) {
  if (!s || s.length === 0) return "";

  let start = 0;
  let maxLen = 1;

  function expand(left, right) {
    while (left >= 0 && right < s.length && s[left] === s[right]) {
      const len = right - left + 1;
      if (len > maxLen) {
        start = left;
        maxLen = len;
      }
      left--;
      right++;
    }
  }

  for (let i = 0; i < s.length; i++) {
    expand(i, i);     // odd-length palindromes
    expand(i, i + 1); // even-length palindromes
  }

  return s.substring(start, start + maxLen);
}

// ── Test Cases ──────────────────────────────────────────────────────────────

const tests = [
  // Basic cases
  { input: "babad",        expected: ["bab", "aba"] },
  { input: "cbbd",         expected: ["bb"] },
  { input: "a",            expected: ["a"] },
  { input: "",             expected: [""] },

  // Entire string is a palindrome
  { input: "racecar",      expected: ["racecar"] },
  { input: "abba",         expected: ["abba"] },
  { input: "aa",           expected: ["aa"] },

  // All same characters
  { input: "aaaa",         expected: ["aaaa"] },
  { input: "aaa",          expected: ["aaa"] },

  // No palindrome longer than 1
  { input: "abcde",        expected: ["a", "b", "c", "d", "e"] },

  // Palindrome in the middle / edges
  { input: "abacdfgdcaba", expected: ["aba"] },
  { input: "aabbccbbaa",   expected: ["aabbccbbaa"] },
  { input: "abaxyzzyxf",   expected: ["xyzzyx"] },

  // Single repeated pair
  { input: "cddb",         expected: ["dd"] },

  // Longer strings
  { input: "forgeeksskeegfor", expected: ["geeksskeeg"] },
  { input: "abcda",        expected: ["a", "b", "c", "d", "a"] },
];

let passed = 0;
let failed = 0;

for (const { input, expected } of tests) {
  const result = parse_expression(input);
  const ok = expected.includes(result) && result.length === expected[0].length;

  if (ok) {
    passed++;
  } else {
    failed++;
    console.log(`FAIL: input="${input}"  got="${result}"  expected one of [${expected}]`);
  }
}

console.log(`\n${passed + failed} tests, ${passed} passed, ${failed} failed`);
